from pathlib import Path

# ---------- Site Builder ----------
p = Path('site-builder.html')
s = p.read_text(encoding='utf-8')
marker = '/* APPLE_SEED_HERO_SLIDER_V1 */'
if marker not in s:
    css = r'''
/* APPLE_SEED_HERO_SLIDER_V1 */
#heroSliderPanel .slider-frame{position:relative;width:100%;aspect-ratio:16/10;border:1px solid #dfe5ed;border-radius:12px;overflow:hidden;background:#f5f7fa;display:flex;align-items:center;justify-content:center;margin-bottom:8px}
#heroSliderPanel .slider-frame img{width:100%;height:100%;object-fit:contain;display:block;background:#eef1f5}
#heroSliderPanel .slider-list{display:grid;gap:6px;max-height:270px;overflow:auto;margin-top:8px}
#heroSliderPanel .slider-item{display:grid;grid-template-columns:56px 1fr auto;gap:7px;align-items:center;border:1px solid #e3e8ef;border-radius:9px;padding:5px;background:#fff;cursor:grab}
#heroSliderPanel .slider-item.active{border-color:#1769ff;box-shadow:0 0 0 2px #1769ff22;background:#f7faff}
#heroSliderPanel .slider-thumb{width:56px;height:40px;border-radius:6px;object-fit:cover;background:#f2f4f7}
#heroSliderPanel .slider-name{font-size:10px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#heroSliderPanel .slider-actions{display:flex;gap:3px}
#heroSliderPanel .slider-actions button{border:1px solid #d8dee8;background:#fff;border-radius:6px;padding:4px 6px;font-size:10px;cursor:pointer}
#heroSliderPanel .slider-actions .del{color:#b42318;border-color:#efb4b4}
#heroSliderPanel .slider-empty{font-size:10px;color:#667085;padding:7px;border:1px dashed #cfd6df;border-radius:8px;text-align:center}
'''
    s = s.replace('/* V4 robust image controls */', css + '\n/* V4 robust image controls */', 1)
    html = '''<div class="panel" id="heroSliderPanel" hidden><h3>🖼️ Hero Slider — nhiều ảnh</h3><div class="muted" style="margin-bottom:8px">Ảnh tự co vừa khung Slider, không làm tràn layout. Có thể thêm nhiều ảnh, đổi ảnh, xóa và kéo để sắp xếp.</div><div class="slider-frame"><img id="heroSliderPreview" alt="Hero Slider"></div><input id="heroSliderFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden><div class="grid2"><button class="btn primary" id="heroSliderAdd" type="button">＋ Thêm ảnh</button><button class="btn" id="heroSliderReset" type="button">↺ Ảnh gốc</button></div><div id="heroSliderList" class="slider-list"></div><div class="muted" style="margin-top:7px">Tối đa 20MB/ảnh. Xóa ảnh chỉ xóa khỏi Slider, không xóa file Media Library.</div></div>\n'''
    s = s.replace('  <div class="panel" id="pageDesignPanel">', html + '  <div class="panel" id="pageDesignPanel">', 1)
    js = r'''\n/* APPLE_SEED_HERO_SLIDER_JS_V1 */\nfunction heroSliderTarget(){\n  if(!doc)return null;\n  return doc.querySelector('.as3-stage')||doc.querySelector('.shop-photo')||doc.querySelector('.hero .shop-photo');\n}\nfunction heroSliderItem(){\n  const target=heroSliderTarget();\n  if(!target)return null;\n  const sel=stableSelector(target);\n  if(!draft.items[sel])draft.items[sel]={styles:{desktop:{},mobile:{}}};\n  const item=draft.items[sel];\n  item.heroSlider=Array.isArray(item.heroSlider)?item.heroSlider:[];\n  return item;\n}\nfunction heroSliderSelected(){\n  const item=heroSliderItem();\n  if(!item)return 0;\n  const n=Math.max(0,item.heroSlider.length-1);\n  item.heroSliderIndex=Math.min(Math.max(Number(item.heroSliderIndex)||0,0),n);\n  return item.heroSliderIndex;\n}\nfunction applyHeroSliderPreview(){\n  const target=heroSliderTarget();\n  const item=heroSliderItem();\n  if(!target||!item)return;\n  clearInterval(window.__appleSeedHeroSliderTimer);\n  window.__appleSeedHeroSliderTimer=null;\n  target.style.setProperty('background-repeat','no-repeat','important');\n  target.style.setProperty('background-position','center','important');\n  target.style.setProperty('background-size','cover','important');\n  const list=item.heroSlider||[];\n  if(!list.length){\n    if(item.bgImage)target.style.setProperty('background-image','url("'+String(item.bgImage).replace(/"/g,'\\"')+'")','important');\n    return;\n  }\n  let idx=heroSliderSelected();\n  const show=()=>{\n    if(!item.heroSlider?.length)return;\n    idx=Math.min(Math.max(idx,0),item.heroSlider.length-1);\n    item.heroSliderIndex=idx;\n    const url=item.heroSlider[idx]?.url||'';\n    if(url)target.style.setProperty('background-image','url("'+String(url).replace(/"/g,'\\"')+'")','important');\n    const prev=document.getElementById('heroSliderPreview');\n    if(prev)prev.src=url||'';\n    renderHeroSliderList();\n  };\n  show();\n  if(list.length>1)window.__appleSeedHeroSliderTimer=setInterval(()=>{idx=(idx+1)%list.length;show()},5000);\n}\nfunction renderHeroSliderList(){\n  const box=document.getElementById('heroSliderList');\n  if(!box)return;\n  const item=heroSliderItem();\n  const list=item?.heroSlider||[];\n  if(!list.length){box.innerHTML='<div class="slider-empty">Chưa có ảnh Slider. Bấm ＋ Thêm ảnh.</div>';const p=document.getElementById('heroSliderPreview');if(p)p.removeAttribute('src');return;}\n  const active=Number(item.heroSliderIndex)||0;\n  box.innerHTML=list.map((x,i)=>`<div class="slider-item ${i===active?'active':''}" draggable="true" data-slider-index="${i}"><img class="slider-thumb" src="${String(x.url||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;')}" alt=""><div class="slider-name">${String(x.name||('Ảnh '+(i+1))).replace(/[&<>]/g,'')}</div><div class="slider-actions"><button type="button" data-slider-up="${i}">↑</button><button type="button" data-slider-down="${i}">↓</button><button type="button" data-slider-change="${i}">Đổi</button><button type="button" class="del" data-slider-del="${i}">×</button></div></div>`).join('');\n  box.querySelectorAll('[data-slider-index]').forEach(el=>{\n    el.addEventListener('click',e=>{if(e.target.closest('button'))return;item.heroSliderIndex=Number(el.dataset.sliderIndex)||0;saveDraft();applyHeroSliderPreview();});\n    el.addEventListener('dragstart',e=>{window.__appleSeedHeroSliderDragIndex=Number(el.dataset.sliderIndex);e.dataTransfer.effectAllowed='move';});\n    el.addEventListener('dragover',e=>e.preventDefault());\n    el.addEventListener('drop',e=>{e.preventDefault();const from=window.__appleSeedHeroSliderDragIndex,to=Number(el.dataset.sliderIndex);if(!Number.isInteger(from)||from===to)return;const moved=item.heroSlider.splice(from,1)[0];item.heroSlider.splice(to,0,moved);item.heroSliderIndex=to;window.__appleSeedHeroSliderDragIndex=null;saveDraft();applyHeroSliderPreview();});\n  });\n  box.querySelectorAll('[data-slider-up]').forEach(b=>b.onclick=()=>heroSliderMove(Number(b.dataset.sliderUp),-1));\n  box.querySelectorAll('[data-slider-down]').forEach(b=>b.onclick=()=>heroSliderMove(Number(b.dataset.sliderDown),1));\n  box.querySelectorAll('[data-slider-del]').forEach(b=>b.onclick=()=>heroSliderDelete(Number(b.dataset.sliderDel)));\n  box.querySelectorAll('[data-slider-change]').forEach(b=>b.onclick=()=>heroSliderChange(Number(b.dataset.sliderChange)));\n}\nfunction heroSliderMove(i,d){const item=heroSliderItem();if(!item)return;const j=i+d;if(j<0||j>=item.heroSlider.length)return;checkpoint();[item.heroSlider[i],item.heroSlider[j]]=[item.heroSlider[j],item.heroSlider[i]];item.heroSliderIndex=j;saveDraft();applyHeroSliderPreview();}\nfunction heroSliderDelete(i){const item=heroSliderItem();if(!item||!item.heroSlider[i])return;if(item.heroSlider.length<=1){toast('Slider phải giữ ít nhất 1 ảnh. Dùng “Ảnh gốc” để bỏ Slider.');return;}checkpoint();item.heroSlider.splice(i,1);item.heroSliderIndex=Math.min(Number(item.heroSliderIndex)||0,item.heroSlider.length-1);item.bgImage=item.heroSlider[item.heroSliderIndex]?.url||'';saveDraft();applyHeroSliderPreview();toast('🗑️ Đã xóa ảnh khỏi Slider');}\nfunction heroSliderChange(i){const input=document.getElementById('heroSliderFile');if(!input)return;input.dataset.replaceIndex=String(i);input.multiple=false;input.value='';input.click();}\nasync function heroSliderAddFiles(files,replaceIndex=null){\n  const arr=[...(files||[])];if(!arr.length)return;\n  const item=heroSliderItem();if(!item)return;\n  checkpoint();\n  try{\n    for(const file of arr){\n      if(!/^image\\/(png|jpe?g|webp|gif)$/i.test(String(file.type||'')))throw new Error('Chỉ nhận PNG, JPG, WEBP hoặc GIF.');\n      if(file.size>20*1024*1024)throw new Error('Ảnh quá lớn (tối đa 20MB/ảnh).');\n      const url=await upload(file);\n      const entry={url,name:file.name||'Hero Slider',alt:'Hero Slider'};\n      if(replaceIndex!==null&&replaceIndex!==undefined){item.heroSlider[Number(replaceIndex)]=entry;replaceIndex=null;}else item.heroSlider.push(entry);\n    }\n    item.heroSliderIndex=Math.min(Number(item.heroSliderIndex)||0,item.heroSlider.length-1);\n    item.bgImage=item.heroSlider[item.heroSliderIndex]?.url||item.bgImage;\n    saveDraft();applyHeroSliderPreview();toast('🖼️ Đã thêm '+arr.length+' ảnh vào Slider');\n  }catch(e){toast('Upload Slider lỗi: '+(e?.message||String(e)));}\n  finally{const input=document.getElementById('heroSliderFile');if(input){input.value='';input.multiple=true;delete input.dataset.replaceIndex;}}\n}\nfunction resetHeroSlider(){const item=heroSliderItem();if(!item)return;checkpoint();delete item.heroSlider;delete item.heroSliderIndex;applyHeroSliderPreview();saveDraft();toast('↺ Đã về ảnh Hero gốc');}\nfunction refreshHeroSliderPanel(){\n  const panel=document.getElementById('heroSliderPanel');if(!panel)return;\n  const target=heroSliderTarget();\n  const show=!!target&&!!selected&&(selected===target||selected.closest?.('.as3-stage')===target);\n  panel.hidden=!show;\n  if(show){renderHeroSliderList();applyHeroSliderPreview();}\n}\ndocument.getElementById('heroSliderAdd')?.addEventListener('click',()=>{const f=document.getElementById('heroSliderFile');f.value='';f.multiple=true;f.dataset.replaceIndex='';f.click();});\ndocument.getElementById('heroSliderReset')?.addEventListener('click',resetHeroSlider);\ndocument.getElementById('heroSliderFile')?.addEventListener('change',e=>{const i=e.target.dataset.replaceIndex;heroSliderAddFiles(e.target.files,i===''?null:Number(i));});\n'''
    anchor="$('deleteImage').onclick=()=>{"
    idx=s.find(anchor)
    if idx<0: raise SystemExit('deleteImage anchor missing')
    s=s[:idx]+js+s[idx:]
    old="$('imagePanel').hidden=!as4ImageCapable(selected);\n  $('stylePanel').hidden=false;"
    new="$('imagePanel').hidden=!as4ImageCapable(selected);\n  refreshHeroSliderPanel();\n  $('stylePanel').hidden=false;"
    if old not in s: raise SystemExit('refreshInspector anchor missing')
    s=s.replace(old,new,1)
    old2="  normalizeHeroCopy();\n  refreshInspector();\n}"
    new2="  normalizeHeroCopy();\n  applyHeroSliderPreview();\n  refreshInspector();\n}"
    if old2 not in s: raise SystemExit('applyAll anchor missing')
    s=s.replace(old2,new2,1)
    p.write_text(s,encoding='utf-8')

# ---------- Live homepage ----------
pi=Path('index.html')
ix=pi.read_text(encoding='utf-8')
live_marker='/* APPLE_SEED_HERO_SLIDER_LIVE_V1 */'
if live_marker not in ix:
    live=r'''\n<script>\n/* APPLE_SEED_HERO_SLIDER_LIVE_V1 */\n(function(){\n  const sb=window.supabaseClient;if(!sb)return;\n  let timer=null,lastKey='';\n  const target=()=>document.querySelector('.as3-stage');\n  function start(list){\n    const el=target();if(!el||!list.length)return;\n    clearInterval(timer);let i=0;\n    const show=()=>{const url=list[i]?.url||'';if(!url)return;el.style.setProperty('background-image','url("'+String(url).replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'")','important');el.style.setProperty('background-size','cover','important');el.style.setProperty('background-position','center','important');el.style.setProperty('background-repeat','no-repeat','important');};\n    show();if(list.length>1)timer=setInterval(()=>{i=(i+1)%list.length;show();},5000);\n  }\n  async function load(){\n    try{\n      const r=await sb.from('site_builder_versions').select('config,version_no').eq('site_key','default').eq('status','published').order('version_no',{ascending:false}).limit(1).maybeSingle();\n      if(r.error||!r.data?.config)return;\n      const item=Object.values(r.data.config.items||{}).find(x=>Array.isArray(x?.heroSlider)&&x.heroSlider.length);\n      if(!item)return;\n      const list=item.heroSlider.filter(x=>x&&x.url);const key=String(r.data.version_no)+'|'+list.map(x=>x.url).join('|');\n      if(key===lastKey)return;lastKey=key;start(list);\n    }catch(e){console.warn('Hero Slider live:',e);}\n  }\n  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load,{once:true});else load();\n  window.addEventListener('load',()=>setTimeout(load,700),{once:true});\n})();\n</script>\n'''
    pos=ix.rfind('</body>')
    if pos<0: raise SystemExit('index body end missing')
    ix=ix[:pos]+live+ix[pos:]
    pi.write_text(ix,encoding='utf-8')

print('hero slider patch prepared')